import{_ as t,o as e,c as o,Q as a}from"./chunks/framework.b67c47e6.js";const n="/assets/account-page.2ed48d29.svg",f=JSON.parse('{"title":"Account Settings","description":"","frontmatter":{},"headers":[],"relativePath":"guide/account/index.md","filePath":"guide/account/index.md","lastUpdated":1790346505000}'),i={name:"guide/account/index.md"},s=a('<h1 id="account-settings" tabindex="-1">Account Settings <a class="header-anchor" href="#account-settings" aria-label="Permalink to &quot;Account Settings&quot;">​</a></h1><p>The Account page lets you manage your personal settings, security, notification preferences, linked sign-in accounts and connected apps. Open it from the account button at the top of the left menu: <strong>Account</strong>.</p><p><img src="'+n+'" alt="The Account page"></p><ol><li>Your account, line and station.</li><li>Two-factor authentication.</li><li>Which messages you get, and the emails about them.</li><li>Google and Microsoft sign-in.</li><li>The applications you connected, such as Claude.</li></ol><h2 id="profile" tabindex="-1">Profile <a class="header-anchor" href="#profile" aria-label="Permalink to &quot;Profile&quot;">​</a></h2><p>The <strong>Account</strong> card shows:</p><ul><li><strong>Username</strong> — Your login name.</li><li><strong>Production line</strong> — Your currently selected production line.</li><li><strong>Production station</strong> — Your currently selected station.</li><li><strong>Language</strong> — A button to change the interface language, shown only if multilanguage is enabled for your account.</li></ul><h2 id="two-factor-authentication-2fa" tabindex="-1">Two-Factor Authentication (2FA) <a class="header-anchor" href="#two-factor-authentication-2fa" aria-label="Permalink to &quot;Two-Factor Authentication (2FA)&quot;">​</a></h2><p>Enable 2FA to add an extra layer of security to your account. When enabled, you&#39;ll need to enter a one-time password (OTP) from your authenticator app each time you log in. The <strong>2FA</strong> card says whether it is enabled.</p><h3 id="setting-up-2fa" tabindex="-1">Setting Up 2FA <a class="header-anchor" href="#setting-up-2fa" aria-label="Permalink to &quot;Setting Up 2FA&quot;">​</a></h3><ol><li>Click <strong>2FA Setup</strong> on the account page.</li><li>Scan the QR code with your authenticator app (Google Authenticator, Authy, etc.).</li><li>Enter the code from the app and click <strong>Save</strong> to confirm.</li></ol><h3 id="disabling-2fa" tabindex="-1">Disabling 2FA <a class="header-anchor" href="#disabling-2fa" aria-label="Permalink to &quot;Disabling 2FA&quot;">​</a></h3><p>Click <strong>2FA Disable</strong>, then <strong>Disable</strong> to confirm.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>The <strong>Notifications</strong> card has two buttons:</p><ul><li><strong>Notifications</strong> — Choose which system messages you receive in your produuz.it messages: <strong>Errors on report generation</strong>, <strong>Produuz.it updates</strong>, <strong>Panels marked as ready</strong>, <strong>Batches marked as ready</strong> and <strong>Delays detected by scheduler</strong>.</li><li><strong>Emails</strong> — Choose when you get an email about messages you receive: never, on each message, when a message is not read within 5 minutes, or one email at the end of the day with all messages.</li></ul><h2 id="linked-accounts" tabindex="-1">Linked Accounts <a class="header-anchor" href="#linked-accounts" aria-label="Permalink to &quot;Linked Accounts&quot;">​</a></h2><p>Link a Google or Microsoft account to sign in faster. Use the Google sign-in button, or <strong>Link</strong> next to Microsoft, and <strong>Unlink</strong> to remove a link. Linking updates your account email to the provider&#39;s. A provider that is not set up yet shows <em>Not available yet</em>.</p><h2 id="connected-apps" tabindex="-1">Connected Apps <a class="header-anchor" href="#connected-apps" aria-label="Permalink to &quot;Connected Apps&quot;">​</a></h2><p><strong>Connected apps</strong> lists the applications you have allowed to read your produuz.it data, such as an AI assistant connected through <a href="/guide/mcp/">MCP</a>. For each one you see what it may access and when it was last used; an app marked <em>not reviewed</em> has not been checked by produuz.it. Click <strong>Disconnect</strong> to revoke its access.</p>',20),r=[s];function c(l,u,d,h,g,p){return e(),o("div",null,r)}const b=t(i,[["render",c]]);export{f as __pageData,b as default};
